}
body .dsh-wc-color {
	width: 44px;
	height: 28px;
	padding: 2px;
	border: 0.5px solid var(--dsw-alias-border-l2, #e6e6e6);
	border-radius: var(--wc-radius-bubble);
	background: var(--dsw-alias-bg-module-platform);
	cursor: pointer;
}
